list_tax_custom_profiles.code:
final response = await client.taxCustomProfiles
    .listTaxCustomProfiles(queryParams: {'limit': 20});
final customProfiles = (response.map as Map)['custom_profiles'] as List;
for (final customProfile in customProfiles) {
  print('${(customProfile as Map)['id']} ${customProfile['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

